package com.household.app.service;
import com.household.app.dto.Requests.*; import com.household.app.entity.*; import com.household.app.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import java.math.*; import java.util.*;
@Service public class InventoryService {
 private final ItemRepository items; private final ConsumptionRepository consumption; private final PurchaseRepository purchases; private final ExpenseRepository expenses; private final ShoppingRepository shopping;
 public InventoryService(ItemRepository i,ConsumptionRepository c,PurchaseRepository p,ExpenseRepository e,ShoppingRepository s){items=i;consumption=c;purchases=p;expenses=e;shopping=s;}
 public List<Item> allItems(String q){return q==null||q.isBlank()?items.findAll():items.findByNameContainingIgnoreCaseOrCategoryContainingIgnoreCase(q,q);}
 public Item item(Long id){return items.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Item not found"));}
 @Transactional public Item create(ItemRequest r){Item i=new Item(r.name().trim(),def(r.category(),"Other"),def(r.unit(),"g"),r.stock(),zero(r.lowStockThreshold()),zero(r.averageUnitPrice()),clean(r.rfidUid()),clean(r.barcode())); return items.save(i);}
 @Transactional public Item update(Long id,ItemRequest r){Item i=item(id);i.setName(r.name().trim());i.setCategory(def(r.category(),"Other"));i.setUnit(def(r.unit(),"g"));i.setStock(r.stock());i.setLowStockThreshold(zero(r.lowStockThreshold()));i.setAverageUnitPrice(zero(r.averageUnitPrice()));i.setRfidUid(clean(r.rfidUid()));i.setBarcode(clean(r.barcode()));return items.save(i);}
 @Transactional public void delete(Long id){items.delete(item(id));}
 @Transactional public Item adjust(Long id,StockAdjustment r){Item i=item(id);BigDecimal next=i.getStock().add(r.quantity());if(next.signum()<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Adjustment would make stock negative");i.setStock(next);return items.save(i);}
 @Transactional public Purchase purchase(PurchaseRequest r){Item i=item(r.itemId());i.setStock(i.getStock().add(r.quantity()));if(r.quantity().signum()>0)i.setAverageUnitPrice(r.totalPrice().divide(r.quantity(),2,RoundingMode.HALF_UP));items.save(i);return purchases.save(new Purchase(i,r.quantity(),r.totalPrice(),r.storeName()));}
 @Transactional public ConsumptionEvent consume(ConsumptionRequest r){if(consumption.existsByEventKey(r.eventKey()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Duplicate eventKey; stock was not deducted again");Item i=items.findByRfidUidIgnoreCase(r.rfidUid().trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"No item mapped to RFID UID"));BigDecimal delta=r.initialWeightGrams().subtract(r.finalWeightGrams());if(delta.signum()<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Final weight must be lower than initial weight for a consumption event");if(i.getStock().compareTo(delta)<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Consumption exceeds recorded stock; reconcile inventory first");i.setStock(i.getStock().subtract(delta));items.save(i);return consumption.save(new ConsumptionEvent(i,r.initialWeightGrams(),r.finalWeightGrams(),delta,r.eventKey()));}
 public List<ConsumptionEvent> history(){return consumption.findTop100ByOrderByCreatedAtDesc();} public List<Purchase> purchaseHistory(){return purchases.findTop100ByOrderByPurchasedAtDesc();} public List<Expense> expenseHistory(){return expenses.findTop100ByOrderBySpentAtDesc();} public List<ShoppingListItem> shoppingList(){return shopping.findAllByOrderByCreatedAtDesc();}
 @Transactional public Expense addExpense(ExpenseRequest r){return expenses.save(new Expense(r.description(),def(r.category(),"Other"),r.amount()));}
 @Transactional public ShoppingListItem addShopping(ShoppingRequest r){Item i=r.itemId()==null?null:item(r.itemId());return shopping.save(new ShoppingListItem(i,r.name(),r.quantity(),def(r.unit(),"item")));}
 @Transactional public ShoppingListItem toggleShopping(Long id){ShoppingListItem s=shopping.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Shopping item not found"));s.setPurchased(!s.isPurchased());return shopping.save(s);}
 @Transactional public void deleteShopping(Long id){shopping.deleteById(id);}
 public Map<String,Object> dashboard(){List<Item> all=items.findAll();BigDecimal value=all.stream().map(i->i.getStock().multiply(zero(i.getAverageUnitPrice()))).reduce(BigDecimal.ZERO,BigDecimal::add);long low=all.stream().filter(i->i.getStock().compareTo(i.getLowStockThreshold())<=0).count();BigDecimal spend=purchases.findTop100ByOrderByPurchasedAtDesc().stream().map(Purchase::getTotalPrice).reduce(BigDecimal.ZERO,BigDecimal::add).add(expenses.findTop100ByOrderBySpentAtDesc().stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add));return Map.of("itemCount",all.size(),"lowStockCount",low,"estimatedStockValue",value,"recentRecordedSpend",spend,"items",all.stream().sorted(Comparator.comparing(Item::getName,String.CASE_INSENSITIVE_ORDER)).toList());}
 private static String def(String s,String d){return s==null||s.isBlank()?d:s.trim();} private static String clean(String s){return s==null||s.isBlank()?null:s.trim().toUpperCase(Locale.ROOT);} private static BigDecimal zero(BigDecimal b){return b==null?BigDecimal.ZERO:b;}
}
